package com.raiiiden.warborn.hybrid;import java.util.*;import java.util.function.*;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.PostChain;import net.minecraft.server.level.ServerPlayer;import com.raiiiden.warborn.common.util.NvgLink2;
public class VisionChecks12{static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}public static class Registry{public Map<String,Entry>shaders=new LinkedHashMap<>();public String currentActiveShader;}public static class Entry{public Boolean forceEnabled=true;public Predicate<Object>activationCondition=x->false;public Object shaderLocation;public Consumer<Object>configurer=x->{};Entry(String s){shaderLocation=s;}}public static class Event{public String getStage(){return "AFTER_LEVEL";}public Delta getPartialTick(){return new Delta();}}public static class Delta{public float getGameTimeDeltaPartialTick(boolean freeze){return .5f;}}
 public static void main(String[]a){var m=Minecraft.INSTANCE;m.player=new ServerPlayer();m.level=new Object();Object foreign=new Object();m.gameRenderer.effect=foreign;NvgLink2.down=true;Registry r=new Registry();r.shaders.put("htvg",new Entry("hybrid"));Vision12.prepare(r);for(int i=0;i<2000;i++){Vision12.prepare(r);Vision12.render(new Event());ok(PostChain.processed==i,"world-stage filter must wait for hands");Vision12.finish(new Delta());}ok(PostChain.created==1&&PostChain.resized==1,"2000 frames must reuse one framebuffer chain");ok(PostChain.closed==0&&PostChain.processed==2000,"no per-frame deletion or skipped vision");ok(m.gameRenderer.effect==foreign,"foreign vanilla effect preserved");ok(!((Minecraft.ActiveRenderer)m.gameRenderer).effectActive,"foreign pain filter paused while NVG owns the view");ok(r.currentActiveShader.equals("htvg"),"registry reports active mode");m.target.width=1200;Vision12.prepare(r);Vision12.prepare(r);ok(PostChain.resized==2&&PostChain.created==1,"window resize only once when dimensions change");r.shaders.get("htvg").forceEnabled=false;r.shaders.put("nvg",new Entry("green"));Vision12.prepare(r);ok(PostChain.created==2&&Vision12.CACHE.size()==2,"bounded second palette cached");r.shaders.get("nvg").forceEnabled=false;r.shaders.get("htvg").forceEnabled=true;Vision12.prepare(r);ok(PostChain.created==2,"switching back reuses cached palette");r.shaders.get("htvg").forceEnabled=false;r.shaders.put("dvg",new Entry("digital"));Vision12.prepare(r);ok(PostChain.created==3&&Vision12.CACHE.size()==2&&PostChain.closed==1,"third palette evicts one old chain");Vision12.ignoreForeignShutdown(m.gameRenderer);ok(m.gameRenderer.effect==foreign,"disable request cannot delete another mod effect");NvgLink2.down=false;Vision12.prepare(r);ok(Vision12.active==null&&Vision12.CACHE.isEmpty()&&PostChain.closed==3,"visor raised releases filters");ok(((Minecraft.ActiveRenderer)m.gameRenderer).effectActive,"original filter enabled state restored when visor rises");NvgLink2.down=true;Vision12.prepare(r);int before=PostChain.created;m.level=new Object();Vision12.prepare(r);ok(PostChain.created==before+1,"new world creates fresh filter");Vision12.clear();Vision12.prepare(r);ok(Vision12.active!=null,"resource reset can rebuild cache");m.player=null;Vision12.prepare(r);ok(Vision12.CACHE.isEmpty()&&Vision12.active==null,"world exit clears GPU owners");System.out.println("NVG_CACHED_2000_FRAMES_SWITCH_RESIZE_FOREIGN_EFFECT_RELOAD_UNLOAD_CHECKS="+n);}}
